from django.db.models import Max


def completar_rutinas_existentes(apps, schema_editor):
    """Rutinas creadas antes de esta migración:
    - días por semana = mayor día usado (mínimo 1); se crean sus días (DiaRutina);
    - las que ya están asignadas quedan PUBLICADAS (las demás, en borrador);
    - cada RutinaEjercicio pasa a tener sus series (SerieRutina) con los mismos valores."""
    Rutina = apps.get_model("gmf", "Rutina")
    DiaRutina = apps.get_model("gmf", "DiaRutina")
    SerieRutina = apps.get_model("gmf", "SerieRutina")
    for rutina in Rutina.objects.all():
        rutina.dias_por_semana = min(max(rutina.detalle.aggregate(m=Max("dia"))["m"] or 1, 1), 7)
        if rutina.asignaciones.exists():
            rutina.estado = "PUBLICADA"
        rutina.save(update_fields=["dias_por_semana", "estado"])
        usados = set(rutina.detalle.values_list("semana", "dia"))
        for semana in range(1, rutina.semanas + 1):
            for dia in range(1, rutina.dias_por_semana + 1):
                usados.add((semana, dia))
        DiaRutina.objects.bulk_create([DiaRutina(rutina=rutina, semana=s, dia=d) for s, d in sorted(usados)])
        for re in rutina.detalle.all():
            SerieRutina.objects.bulk_create([
                SerieRutina(rutina_ejercicio=re, numero=n, repeticiones_min=re.repeticiones_min,
                            repeticiones_max=re.repeticiones_max, descanso_segundos=re.descanso_segundos)
                for n in range(1, re.series + 1)
            ])


